// Turns public/art/*.svg into lib/art-data.generated.ts so scenes can be inlined on any host
// (reading files from public/ at runtime is not reliable on every host). Run: npm run build:art
// A test fails if the generated file is out of date, so it cannot drift.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

export function buildArtModule(root = process.cwd()) {
  const dir = join(root, "public/art");
  const files = readdirSync(dir).filter((f) => f.endsWith(".svg")).sort();
  const entries = files.map((f) => `  ${JSON.stringify("/art/" + f)}: ${JSON.stringify(readFileSync(join(dir, f), "utf8").trim())},`);
  return `// GENERATED by scripts/build-art-data.mjs from public/art/*.svg. Do not edit; run npm run build:art.\nexport const ART_SVG: Record<string, string> = {\n${entries.join("\n")}\n};\n`;
}

if (process.argv[1] && import.meta.url.endsWith(process.argv[1].replace(/\\/g, "/").split("/").pop())) {
  writeFileSync(join(process.cwd(), "lib/art-data.generated.ts"), buildArtModule());
  console.log("lib/art-data.generated.ts written");
}
